verify:
choices = {o: choices[n] for o, n in {'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D'}.items()}; answer = {'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D'}[answer]  # shuffled: original letters
def pair(s):
    a, b = s.replace('\\(', '').replace('\\)', '').strip('() ').split(',')
    return (value(a), value(b))
x, y = symbols('x y')
sols = {(s[x], s[y]) for s in solve([Eq(y, x**2 + 2*x - 3), Eq(y, 2*x + 1)], [x, y], dict=True)}
assert sols == {(2, 5), (-2, -3)}
assert pair(choices[answer]) in sols
assert all(pair(choices[k]) not in sols for k in choices if k != answer)
